package io.scenariomesh.config;
import java.nio.file.Path;import java.time.Duration;import java.util.List;
public record ScenarioMeshConfig(boolean enabled,int workerCount,Duration discoveryTimeout,Duration workerStartupTimeout,Duration workerShutdownTimeout,Path reportingDirectory,List<String> workerJvmArgs){public ScenarioMeshConfig{if(workerCount<1)throw new IllegalArgumentException("Invalid configuration: workers.count must be greater than 0");if(discoveryTimeout==null||discoveryTimeout.isNegative()||discoveryTimeout.isZero())throw new IllegalArgumentException("Invalid configuration: discovery.timeout must be greater than 0");if(workerStartupTimeout==null||workerStartupTimeout.isNegative()||workerStartupTimeout.isZero())throw new IllegalArgumentException("Invalid configuration: workers.startupTimeout must be greater than 0");if(workerShutdownTimeout==null||workerShutdownTimeout.isNegative()||workerShutdownTimeout.isZero())throw new IllegalArgumentException("Invalid configuration: workers.shutdownTimeout must be greater than 0");if(reportingDirectory==null)throw new IllegalArgumentException("Invalid configuration: reporting.directory is required");workerJvmArgs=List.copyOf(workerJvmArgs==null?List.of():workerJvmArgs);}public static ScenarioMeshConfig defaults(Path build){return new ScenarioMeshConfig(true,4,Duration.ofMinutes(2),Duration.ofSeconds(30),Duration.ofSeconds(10),build.resolve("scenariomesh"),List.of());}}
